package com.stark.automation.utils;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.stark.automation.core.exceptions.TestDataException; import java.io.InputStream; import java.util.List;
public final class TestDataReader { private static final ObjectMapper MAPPER = new ObjectMapper(); private TestDataReader() { } public static <T> List<T> list(String resource, TypeReference<List<T>> type) { try (InputStream input = TestDataReader.class.getClassLoader().getResourceAsStream(resource)) { if (input == null) throw new TestDataException("Test data resource not found: " + resource, null); return MAPPER.readValue(input, type); } catch (Exception e) { if (e instanceof TestDataException t) throw t; throw new TestDataException("Unable to read test data: " + resource, e); } } }
